SELECT 900106, 'Ortell can compare the evidence we have already deposited. What did he find?' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900106 AND owner.`chapter`=1)
