SELECT 900107, 'Did you see Jarod clearly? Keep your voice low.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900107 AND owner.`chapter`=1)
