SELECT 900304, 'Defeat 8 relic raiders before their next camp attack.', 'The watchers were only the edge of the force. Defeat relic raiders and hexers at their dig, and bring back eight insignia as proof that their next attack has been broken. This expedition has families in it, and I mean to keep them alive.', 'Speak with Kor Bloodtusk at the Dawnchaser field camp.', '', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900304 AND owner.`chapter`=3)
