SELECT 900310, 'Deliver food to 3 refugee groups and speak with Dezco about his sons and remaining expedition.', 'Redhorn and Cloudhoof breathe, and others still need to eat. Take these three food bundles to the Dawnchaser families, displaced travelers and expedition wounded. Give each group one bundle, then speak with me about the boys and the people who remain. We will carry our grief; we will not leave the living behind.', 'Speak with Sunwalker Dezco at the Dawnchaser field camp.', 'Dawnchaser families supplied', 'Displaced travelers supplied', 'Expedition wounded supplied', 'Expedition plans discussed with Dezco' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900310 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `QuestDescription`=VALUES(`QuestDescription`), `QuestCompletionLog`=VALUES(`QuestCompletionLog`), `ObjectiveText1`=VALUES(`ObjectiveText1`), `ObjectiveText2`=VALUES(`ObjectiveText2`), `ObjectiveText3`=VALUES(`ObjectiveText3`), `ObjectiveText4`=VALUES(`ObjectiveText4`);
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`)
SELECT 900310, 'We will move when the children and the wounded can move. The expedition still has a purpose.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900310 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_request_items` (`ID`, `CompletionText`)
SELECT 900310, 'Each group needs one bundle. When all three have eaten, we can speak about the journey ahead.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900310 AND owner.`chapter`=3)
