INSERT INTO `quest_template` (`ID`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`)
SELECT 900311, 'Deliver the village introduction letter to Mei at the affected settlement.', 'The people at the wayside settlement southwest of here have been facing the same raiders, and hope is wearing thin there. Take my introduction to Mei Barrelbottom at the relief station on the Mudsprocket road. Tell her what our camp has learned and what you are willing to do.', 'Speak with Mei Barrelbottom at the relief station on the Mudsprocket road.', '', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900311 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `QuestDescription`=VALUES(`QuestDescription`), `QuestCompletionLog`=VALUES(`QuestCompletionLog`), `ObjectiveText1`=VALUES(`ObjectiveText1`), `ObjectiveText2`=VALUES(`ObjectiveText2`), `ObjectiveText3`=VALUES(`ObjectiveText3`), `ObjectiveText4`=VALUES(`ObjectiveText4`);
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`)
SELECT 900311, 'Kang speaks well of you. There is work to do here, and people who have forgotten that help can arrive.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900311 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
