SELECT 900409, 'Relight 3 hearths and help 3 recovered villagers restart the village services.', 'The curse is broken; now we rebuild. Light the three marked household hearths and help the first three residents resume their food, medicine and equipment services. Each family needs a different hand.', 'Speak with Mei Barrelbottom at the relief station on the Mudsprocket road.', 'Household hearth 1 relit', 'Household hearth 2 relit', 'Household hearth 3 relit', 'Village services restarted' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900409 AND owner.`chapter`=4)
