SELECT 900410, 'Accept the village''s pledge of aid and nominate Mei as its future supply liaison.', 'You stayed when we could not help ourselves. Let me put the village''s promise in writing. Ask Mei to become our supply liaison, then return to me to accept our pledge.', 'Speak with Yi-Mo Longbrow at the village relief camp.', 'Mei named supply liaison', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900410 AND owner.`chapter`=4)
